      "html": "<button class=\"button\">\n  <span class=\"button-text\">Button</span>\n  <span class=\"tooltip\">Tooltip</span>\n</button>",
      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by bociKond - Tags: tooltip, button, hover, click, transition, hover effect, transparent, dashed */\n.button {\n  --clr: #DA5552;\n  --clr-white: #e3e3e3;\n  padding: .75rem 3rem;\n  border: 4px dashed var(--clr);\n  background-color: transparent;\n  color: var(--clr);\n  font-weight: bold;\n  position: relative;\n  transition: 200ms;\n  cursor: pointer;\n}\n\n.tooltip {\n  position: absolute;\n  top: calc(-100% - .75rem);\n  left: 50%;\n  transform: translateX(-50%);\n  background-color: var(--clr);\n  color: var(--clr-white);\n  padding: .5rem 2rem;\n  cursor: auto;\n  display: none;\n  animation: showTooltip 300ms ease-in-out;\n  transform-origin: bottom;\n}\n\n.tooltip::after {\n  content: '';\n  position: absolute;\n  width: 0;\n  height: 0;\n  border-style: solid;\n  border-width: 10px 8px 0 8px;\n  border-color: var(--clr) transparent transparent transparent;\n  bottom: -9px;\n  left: 50%;\n  transform: translate(-50%);\n}\n\n.button:hover {\n  background-color: var(--clr);\n  color: var(--clr-white);\n  border-color: transparent;\n}\n\n.button:hover .tooltip {\n  display: block;\n}\n\n@keyframes showTooltip {\n  0% {\n    opacity: 0;\n    transform: scaleY(0) translateX(-50%);\n  }\n\n  100% {\n    opacity: 1;\n    transform: scaleY(1) translateX(-50%);\n  }\n}"
