      "html": "<div class=\"loader\">\n  <div class=\"clockLoader\">\n    <div class=\"clockHand minuteHand\"></div>\n    <div class=\"clockHand hourHand\"></div>\n  </div>\n  <div class=\"decorativeElementContainer\">\n    <div class=\"decorativeElement decorativeElement1\"></div>\n    <div class=\"decorativeElement decorativeElement2\"></div>\n  </div>\n</div>",
      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by Subaashbala  - Tags: glassmorphism, animation, loader, circle loader, box-shadow, loading animation */\n.loader {\n  position: relative;\n  --duration: 1500ms; /* minute hand's rotation time duration */\n}\n.clockLoader {\n  width: 15em;\n  aspect-ratio: 1;\n  border-radius: 50%;\n  border: 0.25em solid black;\n  background: rgba(255, 255, 255, 0.5);\n  box-shadow: 0px 0px 25px rgba(0, 0, 0, 0.171);\n  backdrop-filter: blur(10px);\n  z-index: 100;\n  animation: floatEffect 15s linear infinite alternate;\n}\n.clockLoader::after {\n  content: \"\";\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -65%);\n  width: 0.5em;\n  aspect-ratio: 1;\n  border-radius: 50%;\n  background-color: black;\n}\n.clockHand {\n  position: absolute;\n  background-color: black;\n  border-radius: 5em;\n  width: 0.25em;\n  transform-origin: bottom;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -100%);\n}\n.hourHand {\n  height: 20%;\n  animation: rotateHand calc(12 * var(--duration)) linear infinite;\n}\n.minuteHand {\n  height: 30%;\n  animation: rotateHand var(--duration) linear infinite;\n}\n.decorativeElementContainer {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform-origin: center center;\n  animation: rotate calc(50 * var(--duration)) linear infinite;\n  z-index: -1;\n  transform: translate(-50%, -50%);\n}\n.decorativeElement {\n  position: relative;\n  width: 7em;\n  aspect-ratio: 1;\n  border-radius: 50%;\n  z-index: -1;\n}\n.decorativeElement1 {\n  left: 50% !important;\n  background: orangered;\n  animation: floatEffect 16ss linear infinite;\n}\n.decorativeElement2 {\n  right: 55%;\n  background: hotpink;\n}\n@keyframes rotateHand {\n  to {\n    transform: translate(-50%, -100%) rotate(360deg);\n  }\n}\n@keyframes rotate {\n  to {\n    transform: translate(-50%, -50%) rotateZ(360deg);\n  }\n}\n@keyframes floatEffect {\n  0% {\n    transform: translate(0);\n  }\n  100% {\n    transform: translate(0, 2em);\n  }\n}"
