      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by adilsarfraz02  - Tags: loader, spinner, smooth, custom, transition, effect loader, loading animation */\n.custom-loader {\n  width: 40px;\n  height: 10px;\n  color: #f000b4;\n  background: radial-gradient(farthest-side, currentColor 90%, #0000) left /\n      10px 10px,\n    radial-gradient(farthest-side, currentColor 90%, #0000) center/10px 10px,\n    radial-gradient(farthest-side, currentColor 90%, #0000) right / 10px 10px,\n    linear-gradient(currentColor 0 0) center/100% 4px;\n  background-repeat: no-repeat;\n  position: relative;\n  animation: s6 2s infinite linear;\n}\n.custom-loader:before,\n.custom-loader:after {\n  content: \"\";\n  position: absolute;\n  inset: 0;\n  background: inherit;\n  animation: inherit;\n  --s: calc(50% - 5px);\n  animation-direction: reverse;\n}\n.custom-loader:after {\n  --s: calc(5px - 50%);\n}\n\n@keyframes s6 {\n  0% {\n    transform: translate(var(--s, 0)) rotate(0);\n  }\n  100% {\n    transform: translate(var(--s, 0)) rotate(1turn);\n  }\n}"
