      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by carhtube  - Tags: animation, loading, loader, circle loader, click animation, effect loader, bounce animation, 3d loader */\n.loader {\n  background: linear-gradient(\n    90deg,\n    #6f22ff,\n    #00aaff,\n    #2cc92c,\n    #00aaff,\n    #6f22ff\n  );\n  background-size: 600% 600%;\n  width: 100px;\n  height: 100px;\n  border-radius: 50%;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  animation: neonRotate 10s linear infinite;\n  position: relative;\n}\n.circleMiddle {\n  background-color: rgb(255, 255, 255);\n  width: 80px;\n  height: 80px;\n  border-radius: 50%;\n  z-index: 99;\n}\n.worm {\n  position: absolute;\n  width: 20px;\n  height: 105px;\n  background-color: hsl(0, 0%, 100%);\n  border-radius: 5px;\n  animation: rotateWorm 4s linear infinite;\n  z-index: 80;\n}\n@keyframes neonRotate {\n  0%,\n  100% {\n    background-position: 0% 0%;\n  }\n  25%,\n  75% {\n    background-position: 100% 0%;\n  }\n  50% {\n    background-position: 0% 100%;\n  }\n}\n@keyframes rotateWorm {\n  from {\n    transform: rotate(0deg);\n  }\n  to {\n    transform: rotate(360deg);\n  }\n}"
