      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by gharsh11032000 - Tags: simple, gradient, card, hover effect */\n.card {\n  position: relative;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 320px;\n  box-shadow: 0 10px 20px rgba(0, 0, 0, 0.2);\n  padding: 32px;\n  overflow: hidden;\n  border-radius: 10px;\n  transition: all 0.5s cubic-bezier(0.23, 1, 0.320, 1);\n}\n\n.content {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 20px;\n  color: #e8e8e8;\n  transition: all 0.5s cubic-bezier(0.23, 1, 0.320, 1);\n}\n\n.content .heading {\n  font-weight: 700;\n  font-size: 32px;\n}\n\n.content .para {\n  line-height: 1.5;\n}\n\n.content .btn {\n  color: #e8e8e8;\n  text-decoration: none;\n  padding: 10px;\n  font-weight: 600;\n  border: none;\n  cursor: pointer;\n  background: linear-gradient(-45deg, #f89b29 0%, #ff0f7b 100% );\n  border-radius: 5px;\n  box-shadow: 0 5px 10px rgba(0, 0, 0, 0.2);\n}\n\n.card::before {\n  content: \"\";\n  position: absolute;\n  left: 0;\n  bottom: 0;\n  width: 100%;\n  height: 5px;\n  background: linear-gradient(-45deg, #f89b29 0%, #ff0f7b 100% );\n  z-index: -1;\n  transition: all 0.5s cubic-bezier(0.23, 1, 0.320, 1);\n}\n\n.card:hover::before {\n  height: 100%;\n}\n\n.card:hover {\n  box-shadow: none;\n}\n\n.card:hover .btn {\n  color: #212121;\n  background: #e8e8e8;\n}\n\n.content .btn:hover {\n  outline: 2px solid #e8e8e8;\n  background: transparent;\n  color: #e8e8e8;\n}\n\n.content .btn:active {\n  box-shadow: none;\n}"
