      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by Spacious74  - Tags: neumorphism, animation, 3d, card, realistic, social media */\n.outer {\n  width: 300px;\n  height: 250px;\n  border-radius: 10px;\n  padding: 1px;\n  background: radial-gradient(circle 230px at 0% 0%, #ffffff, #0c0d0d);\n  position: relative;\n}\n\n.dot {\n  width: 5px;\n  aspect-ratio: 1;\n  position: absolute;\n  background-color: #fff;\n  box-shadow: 0 0 10px #ffffff;\n  border-radius: 100px;\n  z-index: 2;\n  right: 10%;\n  top: 10%;\n  animation: moveDot 6s linear infinite;\n}\n\n@keyframes moveDot {\n  0%,\n  100% {\n    top: 10%;\n    right: 10%;\n  }\n  25% {\n    top: 10%;\n    right: calc(100% - 35px);\n  }\n  50% {\n    top: calc(100% - 30px);\n    right: calc(100% - 35px);\n  }\n  75% {\n    top: calc(100% - 30px);\n    right: 10%;\n  }\n}\n\n.card {\n  z-index: 1;\n  width: 100%;\n  height: 100%;\n  border-radius: 9px;\n  border: solid 1px #202222;\n  background-size: 20px 20px;\n  background: radial-gradient(circle 280px at 0% 0%, #444444, #0c0d0d);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  position: relative;\n  flex-direction: column;\n  color: #fff;\n}\n.ray {\n  width: 220px;\n  height: 45px;\n  border-radius: 100px;\n  position: absolute;\n  background-color: #c7c7c7;\n  opacity: 0.4;\n  box-shadow: 0 0 50px #fff;\n  filter: blur(10px);\n  transform-origin: 10%;\n  top: 0%;\n  left: 0;\n  transform: rotate(40deg);\n}\n\n.card .text {\n  font-weight: bolder;\n  font-size: 4rem;\n  background: linear-gradient(45deg, #000000 4%, #fff, #000);\n  background-clip: text;\n  color: transparent;\n}\n\n.line {\n  width: 100%;\n  height: 1px;\n  position: absolute;\n  background-color: #2c2c2c;\n}\n.topl {\n  top: 10%;\n  background: linear-gradient(90deg, #888888 30%, #1d1f1f 70%);\n}\n.bottoml {\n  bottom: 10%;\n}\n.leftl {\n  left: 10%;\n  width: 1px;\n  height: 100%;\n  background: linear-gradient(180deg, #747474 30%, #222424 70%);\n}\n.rightl {\n  right: 10%;\n  width: 1px;\n  height: 100%;\n}"
