    "html": {
      "html": "<div id=\"menuToggle\">\n  <input id=\"checkbox\" type=\"checkbox\">\n  <label class=\"toggle\" for=\"checkbox\">\n      <div class=\"bar bar--top\"></div>\n      <div class=\"bar bar--middle\"></div>\n      <div class=\"bar bar--bottom\"></div>\n  </label>\n</div>",
      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by vk-uiux - Tags: animation, switch, hamburger, toggle, css, click effect, toggle switch, css effect, click animation */\n#checkbox {\n  display: none;\n}\n\n.toggle {\n  position: relative;\n  width: 40px;\n  cursor: pointer;\n  margin: auto;\n  display: block;\n  height: calc(4px * 3 + 11px * 2);\n}\n\n.bar {\n  position: absolute;\n  left: 0;\n  right: 0;\n  height: 4px;\n  border-radius: calc(4px / 2);\n  background: #7b52b9;\n  color: inherit;\n  opacity: 1;\n  transition: none 0.35s cubic-bezier(.5,-0.35,.35,1.5) 0s;\n}\n\n/***** Collapse Animation *****/\n\n.bar--top {\n  bottom: calc(50% + 11px + 4px/ 2);\n  transition-property: bottom,margin,transform;\n  transition-delay: calc(0s + 0.35s),0s,0s;\n}\n\n.bar--middle {\n  top: calc(50% - 4px/ 2);\n  transition-property: top,opacity;\n  transition-duration: 0.35s,0s;\n  transition-delay: calc(0s + 0.35s * 1.3),calc(0s + 0.35s * 1.3);\n}\n\n.bar--bottom {\n  top: calc(50% + 11px + 4px/ 2);\n  transition-property: top,transform;\n  transition-delay: 0s;\n}\n\n#checkbox:checked + .toggle .bar--top {\n  bottom: calc(50% - 11px - 4px);\n  margin-bottom: calc(11px + 4px/ 2);\n  transform: rotate(45deg);\n  transition-delay: calc(0s + 0.35s * .3),calc(0s + 0.35s * 1.3),calc(0s + 0.35s * 1.3);\n}\n\n#checkbox:checked + .toggle .bar--middle {\n  top: calc(50% + 11px);\n  opacity: 0;\n  transition-duration: 0.35s,0s;\n  transition-delay: 0s,calc(0s + 0.35s);\n}\n\n#checkbox:checked + .toggle .bar--bottom {\n  top: calc(50% - 4px/ 2);\n  transform: rotate(-45deg);\n  transition-delay: calc(0s + 0.35s * 1.3),calc(0s + 0.35s * 1.3);\n}"
    },
