      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by AmIt-DasIT - Tags: switch, animated */\n.checkbox {\n  width: 223px;\n  height: 60px;\n  background-color: #d0d0d0;\n  border-radius: 30px;\n  position: relative;\n  color: black;\n  overflow: hidden;\n}\n\n#checkbox_toggle {\n  display: none;\n}\n\n.checkbox .toggle {\n  width: 100px;\n  height: 50px;\n  position: absolute;\n  border-radius: 30px;\n  left: 5px;\n  cursor: pointer;\n  background: linear-gradient(40deg, #FF0080,#FF8C00 70%);\n  transition: 0.4s;\n  box-shadow: 0px 0px 3px rgb(255, 255, 20), 0px 0px 5px rgb(255, 255, 20);\n}\n\n.checkbox .slide {\n  width: 230px;\n  height: 60px;\n  display: flex;\n  align-items: center;\n  justify-content: space-around;\n  cursor: pointer;\n}\n\n.checkbox .slide .text {\n  font-size: 16px;\n  font-weight: 700;\n  z-index: 100;\n  cursor: pointer;\n}\n\n.check:checked + .checkbox .slide .toggle {\n  transform: translateX(113px);\n  background: linear-gradient(40deg, #8983F7, #A3DAFB 70%);\n  box-shadow: -0px -0px 10px #8983F7, -0px -0px 3px #8983F7;\n}\n\n.check:checked + .checkbox .slide {\n  background-color: #0a1929;\n  color: #fff;\n}"
