      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by MetaBlue2000  - Tags: red, green, minimalist, switch, click animation */\n.switch {\n  font-size: 17px;\n  position: relative;\n  display: inline-block;\n  width: 3.5em;\n  height: 01em;\n}\n\n.switch input {\n  opacity: 0;\n  width: 0;\n  height: 0;\n}\n\n.slider {\n  position: absolute;\n  cursor: pointer;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  background-color: #ff6a59;\n  transition: 0.4s;\n  border-radius: 30px;\n}\n\n.slider:before {\n  position: absolute;\n  content: \"✕\";\n  display: grid;\n  text-align: center;\n  vertical-align: middle;\n  place-items: center;\n  font-size: 1em;\n  font-weight: 900;\n  width: 2em;\n  aspect-ratio: 1;\n  border-radius: 50%;\n  left: 0;\n  top: 50%;\n  transform: translate(0, -50%);\n  color: white;\n  background-color: #ff3c00;\n  border: 1px solid #ba0300;\n  transition: 0.4s;\n}\n\n.switch input:checked + .slider {\n  background-color: teal;\n}\n\n.switch input:checked + .slider:before {\n  content: \"\\002713\";\n  color: teal;\n  background: paleturquoise;\n  border: 1px solid rgba(0, 128, 128, 0.514);\n  transform: translate(1.75em, -50%) rotateZ(360deg);\n}"
