      "html": "<label class=\"switch\">\n  <input type=\"checkbox\" />\n  <span class=\"slider\"></span>\n</label>",
      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by BurgiSimon  - Tags: simple, animation, red, green, switch, animated, css, toggle switch */\n/* The switch - the box around the slider */\n.switch {\n  font-size: 17px;\n  position: relative;\n  display: inline-block;\n  width: 4.5em;\n  height: 2em;\n}\n\n/* Hide default HTML checkbox */\n.switch input {\n  opacity: 0;\n  width: 0;\n  height: 0;\n}\n\n/* The slider */\n.slider {\n  position: absolute;\n  cursor: pointer;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  background-color: #ff3636;\n  transition: 0.1s;\n  transition-delay: 0.2s;\n  border-radius: 30px;\n}\n\n.slider:before {\n  position: absolute;\n  content: \"\";\n  height: 1.4em;\n  width: 1.4em;\n  border-radius: 20px;\n  left: 0.3em;\n  bottom: 0.3em;\n  background-color: white;\n  transition-delay: 0.2s;\n  transition: 0.1s;\n}\n\n.switch input:checked + .slider {\n  transition-delay: 0.2s;\n  background-color: #00c763;\n}\n\n.switch input:focus + .slider {\n  transition-delay: 0.2s;\n  box-shadow: 0 0 1px #00c763;\n}\n\n.switch input:checked + .slider:before {\n  transform: translateX(2.5em);\n  transition-delay: 0.2s;\n  transition-duration: 0.1s;\n}\n\n/* Animation Right */\n@keyframes slideRight {\n  0% {\n    transform: translateX(0) translateY(0);\n  }\n  20% {\n    transform: translateX(0.5em) translateY(-1.5em);\n  }\n  40% {\n    transform: translateX(1em) translateY(-1.75em); /* Highest Point */\n  }\n  60% {\n    transform: translateX(1.5em) translateY(-1.5em);\n  }\n  80% {\n    transform: translateX(2em) translateY(-1.25em);\n  }\n  100% {\n    transform: translateX(2.5em) translateY(0);\n  }\n}\n\n/* Slide Animation Left */\n@keyframes slideLeft {\n  0% {\n    transform: translateX(2.5em) translateY(0);\n  }\n  20% {\n    transform: translateX(2em) translateY(-0.25em);\n  }\n  40% {\n    transform: translateX(1.5em) translateY(-0.5em); /* Highest Point */\n  }\n  60% {\n    transform: translateX(1em) translateY(-0.75em);\n  }\n  80% {\n    transform: translateX(0.5em) translateY(-0.5em);\n  }\n  100% {\n    transform: translateX(0) translateY(0);\n  }\n}\n\n.switch input:checked + .slider:before {\n  animation: slideRight 0.15s forwards;\n}\n\n.switch input:not(:checked) + .slider:before {\n  animation: slideLeft 0.15s forwards;\n}"
