      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by Saiyed-Tanvir - Tags: switch, animated, lever */\n.tgl {\n  position: relative;\n  display: inline-block;\n  width: 5em;\n  height: 1em;\n}\n\n.tgl input {\n  display: none;\n}\n\n.slider {\n  position: absolute;\n  cursor: pointer;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  background-color: #ccc;\n  transition: .4s;\n  border-radius: 30px;\n}\n\n.slider:before {\n  position: absolute;\n  content: \"\";\n  height: 3.4em;\n  width: 1.4em;\n  border-radius: 20px;\n  left: 0.3em;\n  bottom: -1.3em;\n  background-color: #ffffff;\n  box-shadow: 0px 0px 5px #0009;\n  transition: 1s cubic-bezier(0.49, -1.3, 0.45, 2.44);\n}\n\n.tgl input:checked + .slider {\n  background-color: #2196F3;\n}\n\n.tgl input:checked + .slider:before {\n  transform: translateX(2.5em) rotateZ(-180deg);\n}"
