      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by SouravBandyopadhyay - Tags: simple, 3d, action, red, button, switch, input, toggle switch */\n.toggle-button-cover {\n  display: inline-block;\n  position: relative;\n  width: 200px;\n  height: 140px;\n  box-sizing: border-box;\n}\n\n.button-cover:before {\n  counter-increment: button-counter;\n  content: counter(button-counter);\n  position: absolute;\n  right: 0;\n  bottom: 0;\n  color: #d7e3e3;\n  font-size: 12px;\n  line-height: 1;\n  padding: 5px;\n}\n\n.button-cover,\n.knobs,\n.layer {\n  position: absolute;\n  top: 0;\n  right: 0;\n  bottom: 0;\n  left: 0;\n}\n\n.button {\n  position: relative;\n  top: 50%;\n  width: 74px;\n  height: 36px;\n  margin: -20px auto 0 auto;\n  overflow: hidden;\n}\n\n.button.r,\n.button.r .layer {\n  border-radius: 100px;\n}\n\n.checkbox {\n  position: relative;\n  width: 100%;\n  height: 100%;\n  padding: 0;\n  margin: 0;\n  opacity: 0;\n  cursor: pointer;\n  z-index: 3;\n}\n\n.knobs {\n  z-index: 2;\n}\n\n.layer {\n  width: 100%;\n  background-color: #ebf7fc;\n  transition: 0.3s ease all;\n  z-index: 1;\n}\n\n#button-2 .knobs:before,\n#button-2 .knobs:after {\n  content: 'YES';\n  position: absolute;\n  top: 4px;\n  left: 4px;\n  width: 20px;\n  height: 10px;\n  color: #fff;\n  font-size: 10px;\n  font-weight: bold;\n  text-align: center;\n  line-height: 1;\n  padding: 9px 4px;\n  background-color: #03f480;\n  border-radius: 50%;\n  transition: 0.3s ease all;\n}\n\n#button-2 .knobs:before {\n  content: 'YES';\n}\n\n#button-2 .knobs:after {\n  content: 'NO';\n}\n\n#button-2 .knobs:after {\n  right: -28px;\n  left: auto;\n  background-color: #f44336;\n}\n\n#button-2 .checkbox:checked + .knobs:before {\n  left: -28px;\n}\n\n#button-2 .checkbox:checked + .knobs:after {\n  right: 4px;\n}\n\n#button-2 .checkbox:checked ~ .layer {\n  background-color: #fcebeb;\n}"
