    "html": {
      "html": "<label class=\"switch\">\n  <input checked=\"\" type=\"checkbox\" class=\"toggle\">\n  <span class=\"slider\"></span>\n  <span class=\"card-side\"></span>\n</label>",
      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by andrew-demchenk0 - Tags: blue, switch, on, off, toggle, text animation, switcher, color, text, toggle switch */\n.switch {\n  --input-focus: #2d8cf0;\n  --bg-color: #fff;\n  --bg-color-alt: #666;\n  --main-color: #323232;\n  --input-out-of-focus: #ccc;\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  align-items: center;\n  gap: 30px;\n  width: 70px;\n  height: 36px;\n  transform: translateX(calc(50% - 10px));\n}\n\n.toggle {\n  opacity: 0;\n}\n\n.slider {\n  box-sizing: border-box;\n  border-radius: 100px;\n  border: 2px solid var(--main-color);\n  box-shadow: 4px 4px var(--main-color);\n  position: absolute;\n  cursor: pointer;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  background-color: var(--input-out-of-focus);\n  transition: 0.3s;\n}\n\n.slider:before {\n  content: \"off\";\n  box-sizing: border-box;\n  height: 30px;\n  width: 30px;\n  position: absolute;\n  left: 2px;\n  bottom: 1px;\n  border: 2px solid var(--main-color);\n  border-radius: 100px;\n  background-color: var(--bg-color);\n  color: var(--main-color);\n  font-size: 14px;\n  font-weight: 600;\n  text-align: center;\n  line-height: 25px;\n  transition: 0.3s;\n}\n\n.toggle:checked + .slider {\n  background-color: var(--input-focus);\n  transform: translateX(-32px);\n}\n\n.toggle:checked + .slider:before {\n  content: \"on\";\n  transform: translateX(32px);\n}"
    },
