      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by bedirhan-arslan  - Tags: simple, form, hover, active, input, rounded, smooth */\n.formField {\n  margin: 10px;\n  position: relative;\n}\n\n.formField input {\n  padding: 10px 15px;\n  outline: none;\n  border: none;\n  border-radius: 5px;\n  background-color: #f1f1f1;\n  color: #333;\n  font-size: 16px;\n  font-weight: 550;\n  transition: 0.3s ease-in-out;\n  box-shadow: 0 0 0 5px transparent;\n}\n\n.formField input:hover,\n.formField input:focus {\n  box-shadow: 0 0 0 2px #333;\n}\n\n.formField span {\n  position: absolute;\n  left: 0;\n  top: 0;\n  padding: 8px 15px;\n  color: #333;\n  font-size: 16px;\n  font-weight: 600;\n  transition: 0.3s ease-in-out;\n  pointer-events: none;\n}\n\n.formField input:focus + span,\n.formField input:valid + span {\n  transform: translateY(-32px) translateX(-5px) scale(0.95);\n  transition: 0.3s ease-in-out;\n}"
