      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by SanthoshSJ-Dev - Tags: simple, material design, input, animated, line, text */\n.input-wrapper {\n  position: relative;\n  width: 200px;\n  margin: 50px auto;\n}\n\n.input-box {\n  font-size: 16px;\n  padding: 10px 0;\n  border: none;\n  border-bottom: 2px solid #ccc;\n  color: #08AEEA;\n  width: 100%;\n  background-color: transparent;\n  transition: border-color 0.3s ease-in-out;\n}\n\n.underline {\n  position: absolute;\n  bottom: 0;\n  left: 0;\n  width: 100%;\n  height: 2px;\n  background-color: #08AEEA;\n  transform: scaleX(0);\n  transition: transform 0.3s ease-in-out;\n}\n\n.input-box:focus {\n  border-color: #08AEEA;\n  outline: none;\n}\n\n.input-box:focus + .underline {\n  transform: scaleX(1);\n}"
