      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by VijinV - Tags: input, animated */\n.inputbox {\n  position: relative;\n  width: 196px;\n}\n\n.inputbox input {\n  position: relative;\n  width: 100%;\n  padding: 20px 10px 10px;\n  background: transparent;\n  outline: none;\n  box-shadow: none;\n  border: none;\n  color: #23242a;\n  font-size: 1em;\n  letter-spacing: 0.05em;\n  transition: 0.5s;\n  z-index: 10;\n}\n\n.inputbox span {\n  position: absolute;\n  left: 0;\n  padding: 20px 10px 10px;\n  font-size: 1em;\n  color: #8f8f8f;\n  letter-spacing: 00.05em;\n  transition: 0.5s;\n  pointer-events: none;\n}\n\n.inputbox input:valid ~span,\n.inputbox input:focus ~span {\n  color: #45f3ff;\n  transform: translateX(-10px) translateY(-34px);\n  font-size: 0,75em;\n}\n\n.inputbox i {\n  position: absolute;\n  left: 0;\n  bottom: 0;\n  width: 100%;\n  height: 2px;\n  background: #45f3ff;\n  border-radius: 4px;\n  transition: 0.5s;\n  pointer-events: none;\n  z-index: 9;\n}\n\n.inputbox input:valid ~i,\n.inputbox input:focus ~i {\n  height: 44px;\n}"
