    "html": {
      "html": "<input class=\"toggle-checkbox\" id=\"toggle\" type=\"checkbox\" />\n<label class=\"hamburger\" for=\"toggle\">\n  <div class=\"bar\"></div>\n  <div class=\"bar\"></div>\n  <div class=\"bar\"></div>\n</label>",
      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by elijahgummer  - Tags: animation, black, checkbox, hamburger, arrow */\n.toggle-checkbox {\n  display: none;\n}\n\n.hamburger {\n  display: flex;\n  flex-direction: column;\n  justify-content: space-around;\n  width: 35px;\n  height: 24px;\n  cursor: pointer;\n}\n\n.hamburger .bar {\n  width: 100%;\n  height: 4px;\n  background-color: #333;\n  border-radius: 10px;\n  transition:\n    transform 0.3s ease,\n    opacity 0.3s ease;\n  position: relative;\n}\n\n.toggle-checkbox:checked + .hamburger .bar:nth-child(2) {\n  transform: translate(0px, 10px);\n  opacity: 0;\n  transition-delay: 0.3s;\n}\n\n.toggle-checkbox:checked + .hamburger .bar:nth-child(3) {\n  transform: translate(0px, -10px);\n  transition-delay: 0s;\n}\n\n.toggle-checkbox:checked + .hamburger .bar:nth-child(1) {\n  transform: rotate(-45deg) scale(0.7);\n  transition-delay: 0.6s;\n}\n.toggle-checkbox:checked + .hamburger .bar:nth-child(3) {\n  transform: rotate(45deg) scale(0.7);\n  transition-delay: 0.6s;\n}"
    },
