    "html": {
      "html": "<div class=\"bookmark-checkbox\">\n  <input\n    type=\"checkbox\"\n    id=\"bookmark-toggle\"\n    class=\"bookmark-checkbox__input\"\n  />\n  <label for=\"bookmark-toggle\" class=\"bookmark-checkbox__label\">\n    <svg class=\"bookmark-checkbox__icon\" viewBox=\"0 0 24 24\">\n      <path\n        class=\"bookmark-checkbox__icon-back\"\n        d=\"M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z\"\n      ></path>\n      <path class=\"bookmark-checkbox__icon-check\" d=\"M8 11l3 3 5-5\"></path>\n    </svg>\n  </label>\n</div>",
      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by LeonKohli  - Tags: icon, animation, active, checkbox, glow, svg, cool checkbox */\n.bookmark-checkbox {\n  display: inline-block;\n}\n\n.bookmark-checkbox__input {\n  display: none;\n}\n\n.bookmark-checkbox__label {\n  cursor: pointer;\n}\n\n.bookmark-checkbox__icon {\n  width: 2em;\n  height: 2em;\n  fill: none;\n  stroke-width: 2;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n  transition: stroke 0.3s, fill 0.3s;\n}\n\n.bookmark-checkbox__icon-back {\n  stroke: #333;\n  transition: transform 0.3s;\n}\n\n.bookmark-checkbox__icon-check {\n  stroke: #fff;\n  stroke-dasharray: 16;\n  stroke-dashoffset: 16;\n  transition: stroke-dashoffset 0.3s, transform 0.3s;\n  transform: translateX(2px);\n}\n\n.bookmark-checkbox__input:checked\n  + .bookmark-checkbox__label\n  .bookmark-checkbox__icon {\n  fill: #ff5a5f;\n}\n\n.bookmark-checkbox__input:checked\n  + .bookmark-checkbox__label\n  .bookmark-checkbox__icon-back {\n  stroke: #ff5a5f;\n  transform: scale(1.1);\n  animation: bookmark-pop 0.4s ease;\n}\n\n.bookmark-checkbox__input:checked\n  + .bookmark-checkbox__label\n  .bookmark-checkbox__icon-check {\n  stroke-dashoffset: 0;\n  transition-delay: 0.2s;\n}\n\n@keyframes bookmark-pop {\n  0% {\n    transform: scale(1);\n  }\n  50% {\n    transform: scale(1.2);\n  }\n  100% {\n    transform: scale(1.1);\n  }\n}"
    },
