    "added": "2026-09-11",
    "react": "auto",
    "html": {
      "html": "<label class=\"container\">\n  <input checked=\"checked\" type=\"checkbox\">\n  <div class=\"checkmark\"></div>\n  <div class=\"glass-effect\"></div>\n</label>",
      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by TechByElijah - Tags: glassmorphism, blue, checkbox, pulse */\n/* Hide the default checkbox */\n.container input {\n  position: absolute;\n  opacity: 0;\n  cursor: pointer;\n  height: 0;\n  width: 0;\n}\n\n.container {\n  display: inline-block;\n  position: relative;\n  cursor: pointer;\n  font-size: 20px;\n  user-select: none;\n  width: 24px;\n  height: 24px;\n}\n\n  /* Create a custom checkbox */\n.checkmark {\n  position: absolute;\n  top: 0;\n  left: 0;\n  height: 100%;\n  width: 100%;\n  background-color: #fff;\n  border-radius: 50%;\n  border: 1px solid rgba(255, 255, 255, 0.3);\n  transition: background-color 0.3s ease;\n  z-index: 1;\n}\n\n.glass-effect {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%) scale(0);\n  height: 14px;\n  width: 14px;\n  background-color: rgba(255, 255, 255, 0.2);\n  border-radius: 50%;\n  transition: transform 0.3s ease;\n  z-index: 2;\n}\n\n  /* When the checkbox is checked, add a blue background */\n.container input:checked ~ .checkmark {\n  background-color: #2196F3;\n}\n\n  /* Show the glass effect when checked */\n.container input:checked ~ .glass-effect {\n  transform: translate(-50%, -50%) scale(1);\n}\n\n  /* Create the checkmark/indicator (hidden when not checked) */\n.checkmark:after {\n  content: \"\";\n  position: absolute;\n  display: none;\n}\n\n  /* Show the checkmark when checked */\n.container input:checked ~ .checkmark:after {\n  display: block;\n}\n\n  /* Style the checkmark/indicator */\n.container .checkmark:after {\n  content: \"\";\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  width: 5px;\n  height: 10px;\n  border: solid white;\n  border-width: 0 2px 2px 0;\n  transform: translate(-50%, -50%) rotate(45deg);\n}"
    },
