    "html": {
      "html": "<label class=\"container\">\n  <input checked=\"checked\" type=\"checkbox\">\n  <div class=\"checkmark\"></div>\n</label>",
      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by EddyBel - Tags: gradient, checkbox */\n/* Hide the default checkbox */\n.container input {\n  position: absolute;\n  opacity: 0;\n  cursor: pointer;\n  height: 0;\n  width: 0;\n}\n\n.container {\n  display: block;\n  position: relative;\n  cursor: pointer;\n  font-size: 20px;\n  user-select: none;\n}\n\n.container::before {\n  position: absolute;\n  left: 0;\n  top: 0;\n  content: \"\";\n  width: 100%;\n  height: 100%;\n  border-radius: 50%;\n  filter: blur(5px);\n  background-color: #b899ff;\n  background-image: radial-gradient(at 6% 13%, hsla(322,81%,60%,1) 0px, transparent 50%),\nradial-gradient(at 9% 59%, hsla(209,65%,71%,1) 0px, transparent 50%),\nradial-gradient(at 39% 16%, hsla(325,93%,79%,1) 0px, transparent 50%);\n}\n\n/* Create a custom checkbox */\n.checkmark {\n  position: relative;\n  top: 0;\n  left: 0;\n  height: 2em;\n  width: 2em;\n  border-radius: 50%;\n  background-color: rgb(255, 255, 255);\n}\n\n/* When the checkbox is checked, add a blue background */\n.container input:checked ~ .checkmark {\n  height: 2em;\n  width: 2em;\n  border-radius: 50%;\n  position: relative;\n}\n\n.container input:checked ~ .checkmark::before {\n  position: absolute;\n  left: 0;\n  top: 0;\n  right: 0;\n  bottom: 0;\n  margin: auto;\n  width: 65%;\n  height: 65%;\n  content: \"\";\n  border-radius: 50%;\n  background-color: #ff99f0;\n  background-image: radial-gradient(at 86% 29%, hsla(277,65%,76%,1) 0px, transparent 50%),\n  radial-gradient(at 13% 20%, hsla(54,73%,71%,1) 0px, transparent 50%),\n  radial-gradient(at 76% 0%, hsla(145,64%,69%,1) 0px, transparent 50%);\n  animation: animation__checked 600ms normal;\n}\n\n@keyframes animation__checked {\n  0% {\n    opacity: 0;\n    transform: scale(0.8);\n  }\n\n  100% {\n    opacity: 100;\n    transform: scale(1);\n  }\n}"
    },
