      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by Custyyyy - Tags: animation, checkbox */\n#_checkbox {\n display: none;\n}\n\nlabel {\n position: absolute;\n top: 50%;\n right: 0;\n left: 0;\n width: 30px;\n height: 30px;\n margin: 0 auto;\n background-color: #f72414;\n transform: translateY(-50%);\n border-radius: 50%;\n cursor: pointer;\n transition: 0.2s ease transform, 0.2s ease background-color, 0.2s ease box-shadow;\n overflow: hidden;\n z-index: 1;\n}\n\nlabel:before {\n content: \"\";\n position: absolute;\n top: 50%;\n right: 0;\n left: 0;\n width: 24px;\n height: 23px;\n margin: 0 auto;\n background-color: #fff;\n transform: translateY(-50%);\n border-radius: 50%;\n box-shadow: inset 0 7px 10px #ffbeb8;\n transition: 0.2s ease width, 0.2s ease height;\n}\n\nlabel:hover:before {\n transform: translateY(-50%) scale(1.1);\n box-shadow: inset 0 7px 10px #ff9d96;\n}\n\nlabel:active {\n transform: translateY(-50%) scale(0.9);\n}\n\n#tick_mark {\n position: absolute;\n top: 0px;\n right: 0;\n left: 0;\n width: 15px;\n height: 18px;\n margin: 0 auto;\n margin-left: 5px;\n transform: rotateZ(-40deg);\n}\n\n#tick_mark:before, #tick_mark:after {\n content: \"\";\n position: absolute;\n background-color: #fff;\n border-radius: 2px;\n opacity: 0;\n transition: 0.2s ease transform, 0.2s ease opacity;\n}\n\n#tick_mark:before {\n left: 0;\n bottom: 0;\n width: 4px;\n height: 10px;\n box-shadow: -2px 0 5px rgba(0,0,0,0.23);\n transform: translateY(-68px)\n}\n\n#tick_mark:after {\n left: 0;\n bottom: 0;\n width: 100%;\n height: 4px;\n box-shadow: 0 3px 5px rgba(0,0,0,0.23);\n transform: translateX(78px)\n}\n\n#_checkbox:checked + label {\n background-color: #07d410;\n}\n\n#_checkbox:checked + label:before {\n width: 0;\n height: 0;\n}\n\n#_checkbox:checked + label #tick_mark:before, #_checkbox:checked + label #tick_mark:after {\n transform: translate(0);\n opacity: 1;\n}"
