      "html": "<label class=\"checkbox\">\n  <input type=\"checkbox\">\n  <div class=\"checkbox-circle\">\n    <svg viewBox=\"0 0 52 52\" class=\"checkmark\">\n      <circle fill=\"none\" r=\"25\" cy=\"26\" cx=\"26\" class=\"checkmark-circle\"></circle>\n      <path d=\"M16 26l9.2 8.4 17.4-21.4\" class=\"checkmark-kick\"></path>\n    </svg>\n  </div>\n</label>",
      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by mrpumps31232 - Tags: green, minimalist, checkbox, circle, animated, clean */\n.checkbox {\n  position: relative;\n  display: inline-block;\n  vertical-align: middle;\n  margin-right: 20px;\n}\n\n.checkbox input[type=\"checkbox\"] {\n  position: absolute;\n  opacity: 0;\n}\n\n.checkbox-circle {\n  position: relative;\n  display: inline-block;\n  width: 30px;\n  height: 30px;\n  border-radius: 50%;\n  border: 2px solid #aaa;\n  transition: all 0.3s;\n}\n\n.checkbox input[type=\"checkbox\"]:checked ~ .checkbox-circle {\n  background: #4CAF50;\n  border-color: #4CAF50;\n}\n\n.checkmark {\n  position: absolute;\n  top: 0;\n  left: 0;\n  fill: none;\n  stroke: #fff;\n  stroke-width: 3;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n  opacity: 0;\n  transition: all 0.3s;\n}\n\n.checkbox input[type=\"checkbox\"]:checked ~ .checkbox-circle .checkmark {\n  opacity: 1;\n}\n\n.checkmark-circle {\n  stroke-dasharray: 166;\n  stroke-dashoffset: 166;\n  transition: stroke-dashoffset 0.3s;\n}\n\n.checkbox input[type=\"checkbox\"]:checked ~ .checkbox-circle .checkmark-circle {\n  stroke-dashoffset: 0;\n}\n\n.checkmark-kick {\n  stroke-dasharray: 50;\n  stroke-dashoffset: 50;\n  transition: stroke-dashoffset 0.3s;\n}\n\n.checkbox input[type=\"checkbox\"]:checked ~ .checkbox-circle .checkmark-kick {\n  stroke-dashoffset: 0;\n}"
