    "react": "auto",
    "html": {
      "html": "<div class=\"radio-input\">\n  <label class=\"label\">\n    <input\n      type=\"radio\"\n      id=\"value-1\"\n      checked=\"\"\n      name=\"value-radio\"\n      value=\"value-1\"\n    />\n    <p class=\"text\">Designer</p>\n  </label>\n  <label class=\"label\">\n    <input type=\"radio\" id=\"value-2\" name=\"value-radio\" value=\"value-2\" />\n    <p class=\"text\">Student</p>\n  </label>\n  <label class=\"label\">\n    <input type=\"radio\" id=\"value-3\" name=\"value-radio\" value=\"value-3\" />\n    <p class=\"text\">Teacher</p>\n  </label>\n</div>",
      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by Na3ar-17  - Tags: simple, black, hover, input, radio */\n.radio-input {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.radio-input * {\n  box-sizing: border-box;\n  padding: 0;\n  margin: 0;\n}\n\n.radio-input label {\n  display: flex;\n  align-items: center;\n  gap: 15px;\n  padding: 0px 20px;\n  width: 220px;\n  cursor: pointer;\n  height: 50px;\n  position: relative;\n}\n\n.radio-input label::before {\n  position: absolute;\n  content: \"\";\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  width: 220px;\n  height: 45px;\n  z-index: -1;\n  transition: all 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55);\n  border-radius: 10px;\n  border: 2px solid transparent;\n}\n.radio-input label:hover::before {\n  transition: all 0.2s ease;\n  background-color: #2a2e3c;\n}\n\n.radio-input .label:has(input:checked)::before {\n  background-color: #2d3750;\n  border-color: #435dd8;\n  height: 50px;\n}\n.radio-input .label .text {\n  color: #fff;\n}\n\n.radio-input .label input[type=\"radio\"] {\n  background-color: #202030;\n  appearance: none;\n  width: 17px;\n  height: 17px;\n  border-radius: 50%;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n}\n.radio-input .label input[type=\"radio\"]:checked {\n  background-color: #435dd8;\n  -webkit-animation: puls 0.7s forwards;\n  animation: pulse 0.7s forwards;\n}\n\n.radio-input .label input[type=\"radio\"]:before {\n  content: \"\";\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  transition: all 0.1s cubic-bezier(0.165, 0.84, 0.44, 1);\n  background-color: #fff;\n  transform: scale(0);\n}\n\n.radio-input .label input[type=\"radio\"]:checked::before {\n  transform: scale(1);\n}\n\n@keyframes pulse {\n  0% {\n    box-shadow: 0 0 0 0 rgba(255, 255, 255, 0.4);\n  }\n  70% {\n    box-shadow: 0 0 0 8px rgba(255, 255, 255, 0);\n  }\n  100% {\n    box-shadow: 0 0 0 0 rgba(255, 255, 255, 0);\n  }\n}"
    },
