      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by sandeepgopan - Tags: hover, input, theme-switch, radio, futuristic-radio-buttons */\n.radio-compont {\n  display: flex;\n  font-family: 'Courier New', Courier, monospace;\n  padding: 10px;\n  cursor: pointer;\n  transition: 0.3s;\n}\n\n.radio-text {\n  padding: 0px 10px;\n  color: hsl(0, 0%, 50%);\n  font-size: 20px;\n  text-transform: uppercase;\n  font-family: 'Franklin Gothic Medium', 'Arial Narrow', Arial, sans-serif;\n}\n\n.radio-compont:hover {\n  box-shadow: inset 4px 4px 12px #afaeae,inset -4px -4px 12px #ffffffc9;\n  border-radius: 100px;\n}\n\n.radiostyle:checked~.radio-text {\n  color: #E41C23;\n}\n\n.radiostyle {\n  width: 20px;\n  height: 20px;\n}"
