    "added": "2026-09-11",
    "react": "auto",
    "html": {
      "html": "<div class=\"login wrap\">\n  <div class=\"h1\">Login</div>\n  <input pattern=\"^([a-zA-Z0-9_\\-\\.]+)@((\\[[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}\\.)|(([a-zA-Z0-9\\-]+\\.)+))([a-zA-Z]{2,4}|[0-9]{1,3})(\\]?)$\" placeholder=\"Email\" id=\"email\" name=\"email\" type=\"text\">\n  <input placeholder=\"Password\" id=\"password\" name=\"password\" type=\"password\">\n  <input value=\"Login\" class=\"btn\" type=\"submit\">\n</div>",
      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by MikeAndrewDesigner - Tags: animation, form, login form, hover button */\n.login {\n  width: 340px;\n  height: 400px;\n  background: #2c2c2c;\n  padding: 47px;\n  padding-bottom: 57px;\n  color: #fff;\n  border-radius: 17px;\n  padding-bottom: 50px;\n  font-size: 1.3em;\n  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;\n}\n\n.login input[type=\"text\"],\n.login input[type=\"password\"] {\n  opacity: 1;\n  display: block;\n  border: none;\n  outline: none;\n  width: 100%;\n  padding: 13px 18px;\n  margin: 20px 0 0 0;\n  font-size: 0.8em;\n  border-radius: 100px;\n  background: #3c3c3c;\n  color: #fff;\n}\n\n.login input:focus {\n  animation: bounce 1s;\n  -webkit-appearance: none;\n}\n\n.login input[type=submit],\n.login input[type=button],\n.h1 {\n  border: 0;\n  outline: 0;\n  width: 100%;\n  padding: 13px;\n  margin: 40px 0 0 0;\n  border-radius: 500px;\n  font-weight: 600;\n  animation: bounce2 1.6s;\n}\n\n.h1 {\n  padding: 0;\n  position: relative;\n  top: -35px;\n  display: block;\n  margin-bottom: -0px;\n  font-size: 1.3em;\n}\n\n.btn {\n  background: linear-gradient(144deg, #af40ff, #5b42f3 50%, #00ddeb);\n  color: #fff;\n  padding: 16px !important;\n}\n\n.btn:hover {\n  background: linear-gradient(144deg, #1e1e1e , 20%,#1e1e1e 50%,#1e1e1e );\n  color: rgb(255, 255, 255);\n  padding: 16px !important;\n  cursor: pointer;\n  transition: all 0.4s ease;\n}\n\n.login input[type=text] {\n  animation: bounce 1s;\n  -webkit-appearance: none;\n}\n\n.login input[type=password] {\n  animation: bounce1 1.3s;\n}\n\n.ui {\n  font-weight: bolder;\n  background: -webkit-linear-gradient(#B563FF, #535EFC, #0EC8EE);\n  -webkit-background-clip: text;\n  -webkit-text-fill-color: transparent;\n  border-bottom: 4px solid transparent;\n  border-image: linear-gradient(0.25turn, #535EFC, #0EC8EE, #0EC8EE);\n  border-image-slice: 1;\n  display: inline;\n}\n\n@media only screen and (max-width: 600px) {\n  .login {\n    width: 70%;\n    padding: 3em;\n  }\n}\n\n@keyframes bounce {\n  0% {\n    transform: translateY(-250px);\n    opacity: 0;\n  }\n}\n\n@keyframes bounce1 {\n  0% {\n    opacity: 0;\n  }\n\n  40% {\n    transform: translateY(-100px);\n    opacity: 0;\n  }\n}\n\n@keyframes bounce2 {\n  0% {\n    opacity: 0;\n  }\n\n  70% {\n    transform: translateY(-20px);\n    opacity: 0;\n  }\n}"
    },
