      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by vnuny  - Tags: simple, tooltip, animation, black, animated */\n.item-hints {\n  --purple: #720c8f;\n  cursor: pointer;\n  display: flex;\n  justify-content: flex-start;\n  padding-right: 170px;\n}\n.item-hints .hint {\n  margin: 150px auto;\n  position: relative;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n}\n.item-hints .hint-dot {\n  z-index: 3;\n  border: 1px solid #ffe4e4;\n  border-radius: 50%;\n  width: 60px;\n  height: 60px;\n  -webkit-transform: translate(-0%, -0%) scale(0.95);\n  transform: translate(-0%, -0%) scale(0.95);\n  margin: auto;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: white;\n}\n.item-hints .hint-radius {\n  background-color: rgba(255, 255, 255, 0.1);\n  border-radius: 50%;\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  margin: -125px 0 0 -125px;\n  opacity: 0;\n  visibility: hidden;\n  -webkit-transform: scale(0);\n  transform: scale(0);\n}\n.item-hints .hint[data-position=\"1\"] .hint-content {\n  top: 85px;\n  left: 50%;\n  margin-left: 56px;\n}\n.item-hints .hint-content {\n  width: 300px;\n  position: absolute;\n  z-index: 5;\n  padding: 35px 0;\n  opacity: 0;\n  transition: opacity 0.7s ease, visibility 0.7s ease;\n  color: #fff;\n  visibility: hidden;\n  pointer-events: none;\n}\n.item-hints .hint:hover .hint-content {\n  position: absolute;\n  z-index: 5;\n  padding: 35px 0;\n  opacity: 1;\n  -webkit-transition: opacity 0.7s ease, visibility 0.7s ease;\n  transition: opacity 0.7s ease, visibility 0.7s ease;\n  color: #fff;\n  visibility: visible;\n  pointer-events: none;\n}\n.item-hints .hint-content::before {\n  width: 0px;\n  bottom: 29px;\n  left: 0;\n  content: \"\";\n  background-color: #fff;\n  height: 1px;\n  position: absolute;\n  transition: width 0.4s;\n}\n.item-hints .hint:hover .hint-content::before {\n  width: 180px;\n  transition: width 0.4s;\n}\n.item-hints .hint-content::after {\n  -webkit-transform-origin: 0 50%;\n  transform-origin: 0 50%;\n  -webkit-transform: rotate(-225deg);\n  transform: rotate(-225deg);\n  bottom: 29px;\n  left: 0;\n  width: 80px;\n  content: \"\";\n  background-color: #fff;\n  height: 1px;\n  position: absolute;\n  opacity: 1;\n  -webkit-transition: opacity 0.5s ease;\n  transition: opacity 0.5s ease;\n  -webkit-transition-delay: 0s;\n  transition-delay: 0s;\n}\n.item-hints .hint:hover .hint-content::after {\n  opacity: 1;\n  visibility: visible;\n}\n.item-hints .hint[data-position=\"4\"] .hint-content {\n  bottom: 85px;\n  left: 50%;\n  margin-left: 56px;\n}"
