      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by elijahgummer  - Tags: simple, tooltip, green, minimalist, github, clean, transition, hover effect */\n.tooltip-container {\n  --background-tooltip-container: #2ea44f; /* GitHub green color */\n  position: relative;\n  background: var(--background-tooltip-container);\n  cursor: pointer;\n  transition: all 0.2s;\n  width: 16px;\n  height: 16px;\n  border-radius: 6px;\n  font-size: 17px;\n}\n\n.tooltip {\n  --background-tooltip: #6e7681; /* Default background color for tooltip */\n  position: absolute;\n  top: -39px; /* Adjusted top position */\n  left: 50%;\n  transform: translateX(-50%);\n  padding: 0.5em;\n  opacity: 0;\n  pointer-events: none;\n  transition: all 0.3s;\n  background: var(--background-tooltip);\n  color: white; /* Text color */\n  border-radius: 5px;\n  width: 210px;\n  height: 30px;\n  font-size: 13px;\n  text-align: center;\n}\n\n.tooltip::before {\n  position: absolute;\n  content: \"\";\n  height: 0.6em;\n  width: 0.6em;\n  bottom: -0.2em;\n  left: 50%;\n  transform: translate(-50%) rotate(45deg);\n  background: var(\n    --background-tooltip\n  ); /* Use the same background color as the tooltip */\n}\n\n.tooltip-container:hover .tooltip {\n  opacity: 1;\n  visibility: visible;\n  pointer-events: auto;\n}"
