      "css": "/* ORU preview frame */\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 9%;\n  box-sizing: border-box;\n  font-family: system-ui, sans-serif;\n  background:\n    radial-gradient(38% 34% at 50% 42%, rgba(255,255,255,.95), rgba(255,255,255,0) 72%),\n    radial-gradient(rgba(10,10,10,.08) 1.1px, transparent 1.4px) 0 0/20px 20px,\n    #f2f1f0;\n}\n\n/* From Uiverse.io by SouravBandyopadhyay  - Tags: simple, tooltip, animation, text animation, animated, transition, hover effect, hover button */\n.payment-button {\n  --background: #007bff;\n  --text-color: #fff;\n  --hover-background: #0056b3;\n  --hover-text-color: #fff;\n  --border-radius: 4px;\n  --box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);\n\n  display: inline-block;\n  cursor: pointer;\n  font-size: 18px;\n  padding: 0.5em 1.5em;\n  background: var(--background);\n  color: var(--text-color);\n  border: none;\n  border-radius: var(--border-radius);\n  box-shadow: var(--box-shadow);\n  transition: transform 0.2s ease-in-out, background 0.3s ease-in-out,\n    color 0.3s ease-in-out, box-shadow 0.3s ease-in-out;\n  text-transform: uppercase;\n  font-weight: 600;\n  position: relative;\n  overflow: hidden;\n}\n\n.label {\n  z-index: 1;\n}\n\n.price {\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  display: grid;\n  place-items: center;\n  transform-origin: 100%;\n  transform: scale(1);\n  transition: transform 0.3s ease-in-out, color 0.3s ease-in-out,\n    background 0.3s ease-in-out;\n  color: var(--background);\n  background: var(--text-color);\n  border-radius: var(--border-radius);\n  font-weight: bold;\n  font-size: 14px;\n  overflow: hidden;\n}\n\n.payment-button:hover {\n  transform: scale(1.05);\n  background: var(--hover-background);\n  color: var(--hover-text-color);\n  box-shadow: 0 8px 12px rgba(0, 0, 0, 0.2);\n}\n\n.payment-button:hover .price {\n  transform: scale(0);\n}"
